import {memo, useCallback, useMemo} from 'react'
import type {MouseEvent} from 'react'
import {graphql, useFragment} from 'react-relay'
import {useLocation} from 'react-router'

import {getHrefWithQueryParams} from '../../../../../../../routes'
import RouterLink from '../../../../../../common/RouterLink/RouterLink'
import {TestScopesKey} from '../../../../../../packages/Tests/Tests.types'
import {getTestScope, trimAndRemoveColon} from '../../../../../../packages/Tests/Tests.utils'
import {ViewType} from '../../../TestsFilter/TestsViewSelect/TestsViewSelect.utils'

import type {TestScopeName$key} from './__generated__/TestScopeName.graphql'

import styles from './TestScopeName.module.css'

const fragment = graphql`
  fragment TestScopeName on TestScope {
    suite
    package
    class
  }
`

type Props = {
  scopeName: TestScopesKey
  scopeKey: TestScopeName$key
}

function TestScopeName(props: Props) {
  const {scopeName} = props
  const location = useLocation()
  const scopeData = useFragment(fragment, props.scopeKey)

  const links = useMemo(
    () => ({
      suite: getHrefWithQueryParams(location, null, prevParams => ({
        ...prevParams,
        ...getTestScope(TestScopesKey.SUITE, scopeData),
        view: ViewType.PACKAGES,
      })),
      package: getHrefWithQueryParams(location, null, prevParams => ({
        ...prevParams,
        ...getTestScope(TestScopesKey.PACKAGE, scopeData),
        view: ViewType.CLASSES,
      })),
      class: getHrefWithQueryParams(location, null, prevParams => ({
        ...prevParams,
        ...getTestScope(TestScopesKey.CLASS, scopeData),
        view: ViewType.TESTS,
        orderBy: null,
        order: null,
      })),
    }),
    [location, scopeData],
  )
  const onClick = useCallback((event: MouseEvent<any>) => {
    const selection = window.getSelection()
    if (selection != null && selection.toString().length > 0) {
      event.stopPropagation()
      event.preventDefault()
    }
  }, [])
  const renderLink = useCallback(
    (key: TestScopesKey) => {
      const scopeValue = scopeData[key] ?? ''
      return (
        <RouterLink className={styles[key]} to={links[key]} onClick={onClick} draggable="false">
          {scopeValue !== '' ? trimAndRemoveColon(scopeValue) : `<no ${key}>`}
        </RouterLink>
      )
    },
    [scopeData, links, onClick],
  )
  const renderPath = useMemo(
    () => (
      <>
        {scopeName !== TestScopesKey.SUITE && Boolean(scopeData.suite)
          ? renderLink(TestScopesKey.SUITE)
          : null}
        {scopeName !== TestScopesKey.PACKAGE && Boolean(scopeData.package)
          ? renderLink(TestScopesKey.PACKAGE)
          : null}
      </>
    ),
    [renderLink, scopeName, scopeData.package, scopeData.suite],
  )
  return (
    <div className={styles.name}>
      {renderLink(scopeName)}
      <div className={styles.path}>{renderPath}</div>
    </div>
  )
}

export default memo(TestScopeName)
